function cookies(req){return Object.fromEntries(String(req.headers.cookie||'').split(';').filter(Boolean).map(v=>v.trim().split('=')));}
function auth(req,d){const sid=cookies(req).rl_session,s=sessions.get(sid);if(!s||s.expires<Date.now()){if(sid)sessions.delete(sid);return null}if(s.staff_id){const staff=(d.staff||[]).find(v=>v.id===s.staff_id&&v.status==='active');return staff?{owner:null,staff,role:staff.role||'staff',org:d.organizations.find(o=>o.id===staff.organization_id)}:null}const owner=(d.owners||[]).find(o=>o.id===s.owner_id);return owner?{owner,staff:null,role:'owner',org:d.organizations.find(o=>o.id===owner.organization_id)}:null}
