async function transferRegistrationPg(registrationId,targetSessionId,organizationId){if(!databaseStatus.ready)throw Object.assign(new Error('Database is temporarily unavailable.'),{status:503});return database.withTransaction(async client=>{const rr=await client.query('select id,session_id,status from registrations where id=$1 and organization_id=$2 for update',[registrationId,organizationId]);if(!rr.rowCount)throw Object.assign(new Error('Registration not found'),{status:404});if(rr.rows[0].status!=='enrolled')throw Object.assign(new Error('Only active registrations can be transferred.'),{status:409});if(rr.rows[0].session_id===targetSessionId)throw Object.assign(new Error('Choose a different session.'),{status:409});const tr=await client.query('select s.id,s.capacity,s.status,p.organization_id from sessions s join programs p on p.id=s.program_id where s.id=$1 for update of s',[targetSessionId]);if(!tr.rowCount||tr.rows[0].organization_id!==organizationId)throw Object.assign(new Error('Invalid destination session'),{status:403});if(tr.rows[0].status!=='open')throw Object.assign(new Error('Destination session is not open.'),{status:409});const count=await client.query("select (select count(*) from registrations where session_id=$1 and status='enrolled')::int as enrolled,(select count(*) from waitlist where session_id=$1 and status='offered' and (offer_expires_at is null or offer_expires_at>now()))::int as reserved",[targetSessionId]);if(count.rows[0].enrolled+count.rows[0].reserved>=Number(tr.rows[0].capacity))throw Object.assign(new Error('Destination session is no longer available'),{status:409});await client.query('update registrations set session_id=$1 where id=$2',[targetSessionId,registrationId]);return {from:rr.rows[0].session_id,to:targetSessionId}})}
async function setRegistrationStatusPg(registrationId,organizationId,status){if(!databaseStatus.ready)throw Object.assign(new Error('Database is temporarily unavailable.'),{status:503});return database.withTransaction(async client=>{const rr=await client.query('select id,status from registrations where id=$1 and organization_id=$2 for update',[registrationId,organizationId]);if(!rr.rowCount)throw Object.assign(new Error('Registration not found'),{status:404});await client.query('update registrations set status=$1 where id=$2',[status,registrationId]);return {previous:rr.rows[0].status,status}})}
