if(req.method==='POST'&&u.pathname.startsWith('/api/attendance/')){const a=requireAuth(req,res,d);if(!a)return;const pid=u.pathname.split('/').pop(),x=await body(req),r=d.registrations.find(r=>r.participant_id===pid&&r.status==='enrolled'&&orgOwns(d,a.org.id,'session',r.session_id));if(!r)return json(res,403,{error:'Access denied'});const action=String(x.action||'checkin');if(!['checkin','checkout'].includes(action))return json(res,400,{error:'Invalid attendance action'});if(!databaseStatus.ready)return json(res,503,{error:'Attendance is temporarily unavailable.'});const rec={id:id('att'),organization_id:a.org.id,session_id:r.session_id,participant_id:pid,action,at:new Date().toISOString()},actorId=a.owner?.id||a.staff?.id||null;try{await database.withTransaction(async client=>{await client.query('insert into attendance(id,organization_id,session_id,participant_id,action,at,actor_id) values($1,$2,$3,$4,$5,$6,$7)',[rec.id,a.org.id,r.session_id,pid,action,rec.at,actorId]);await client.query('insert into audit_log(id,organization_id,actor_type,actor_id,action,detail,created_at) values($1,$2,$3,$4,$5,$6::jsonb,$7)',[id('audit'),a.org.id,a.owner?'owner':'staff',actorId,'attendance.'+action,JSON.stringify({participant_id:pid,session_id:r.session_id}),rec.at])})}catch(err){return json(res,409,{error:'Attendance could not be saved: '+err.message})}d.attendance.push(rec);d.audit=d.audit||[];d.audit.push({id:id('audit'),organization_id:a.org.id,action:'attendance.'+action,detail:pid,created_at:rec.at});save(d);return json(res,201,{ok:true,attendance:rec});}
