if(req.method==='POST'&&u.pathname.startsWith('/api/waitlist/')&&u.pathname.endsWith('/accept')){const a=requireRole(req,res,d,['owner','manager']);if(!a)return;const wid=u.pathname.split('/')[3],w=d.waitlist.find(v=>v.id===wid);if(!w)return json(res,404,{error:'Waitlist entry not found'});if(!orgOwns(d,a.org.id,'session',w.session_id))return json(res,403,{error:'Access denied'});const regId=id('reg');let accepted;try{accepted=await acceptWaitlistPg(w.id,a.org.id,regId)}catch(e){if(e.message==='This offer has expired.')w.status='expired';save(d);return json(res,e.status||409,{error:e.message})}w.status='accepted';w.accepted_at=new Date().toISOString();let r=d.registrations.find(v=>v.id===accepted.registration_id);if(!r){r={id:accepted.registration_id,organization_id:a.org.id,session_id:accepted.session_id,participant_id:accepted.participant_id,status:'enrolled',payment_status:'pending',created_at:w.accepted_at,waitlist_id:w.id};d.registrations.push(r)}d.audit=d.audit||[];d.audit.push({id:id('audit'),organization_id:a.org.id,action:'waitlist.offer_accepted_by_staff',detail:w.id,created_at:w.accepted_at});save(d);return json(res,200,{ok:true,registration:r});}
